import fs from 'node:fs';
import { execSync } from 'node:child_process';
import readline from 'node:readline';

const KOMINFO_URL = 'https://trustpositif.kominfo.go.id/assets/db/domains.txt'; // Sesuaikan endpoint source feed Anda
const TEMP_RAW = '/tmp/kominfo_raw.txt';
const TARGET_RPZ = '/var/lib/bind/kominfo.rpz';

async function runSync() {
    console.log('[*] Memulai sinkronisasi RPZ Kominfo...');
    
    // 1. Download file blacklist
    try {
        execSync(`curl -s -L "${KOMINFO_URL}" -o ${TEMP_RAW}`, { timeout: 300000 });
    } catch (err) {
        console.error('[-] Gagal mendownload list Kominfo:', err.message);
        return;
    }

    // 2. Generate Header SOA RPZ
    const serial = Math.floor(Date.now() / 1000);
    const header = [
        '$TTL 3600',
        `@ IN SOA localhost. root.localhost. ( ${serial} 3h 1h 1w 1h )`,
        '  IN NS  localhost.',
        '',
        '; --- Generated by Automated ISP RPZ Worker ---',
        ''
    ].join('\n');

    const writeStream = fs.createWriteStream(TARGET_RPZ + '.tmp', { flags: 'w' });
    writeStream.write(header);

    // 3. Stream & Normalisasi Domain
    const fileStream = fs.createReadStream(TEMP_RAW);
    const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

    const seenDomains = new Set();
    let count = 0;

    for await (const line of rl) {
        let domain = line.trim().toLowerCase();
        
        // Bersihkan prefix protokol atau slash jika ada
        domain = domain.replace(/^https?:\/\//, '').replace(/\/.*$/, '').trim();

        // Validasi struktur domain sederhana
        if (!domain || domain.startsWith('#') || domain.includes(' ') || !domain.includes('.')) {
            continue;
        }

        if (!seenDomains.has(domain)) {
            seenDomains.add(domain);
            // Standar RPZ: CNAME . menghasilkan status NXDOMAIN
            writeStream.write(`${domain} CNAME .\n*.${domain} CNAME .\n`);
            count++;
        }
    }

    writeStream.end();

    writeStream.on('finish', () => {
        // 4. Verifikasi sintaks zone sebelum replace file utama
        try {
            execSync(`named-checkzone rpz.kominfo ${TARGET_RPZ}.tmp`);
            fs.renameSync(TARGET_RPZ + '.tmp', TARGET_RPZ);
            execSync(`chown bind:bind ${TARGET_RPZ}`);
            
            // Reload zone tanpa downtime
            execSync(`rndc reload rpz.kominfo in internal-resolver`);
            console.log(`[+] Berhasil sync ${count} domain. RPZ reloaded successfully.`);
        } catch (e) {
            console.error('[-] Sintaks RPZ tidak valid, batalkan reload:', e.message);
        }
    });
}

runSync();